import math
from functools import lru_cache

# This function calculates h(n) = g(n) - n using the identity:
# h(nm) = n*h(m) + m*h(n)
# Base cases: h(1) = 0, h(p) = 1 for prime p.

@lru_cache(maxsize=None)
def calculate_h(n):
    if n == 1:
        return 0

    # Check for prime numbers (h(p) = 1)
    is_prime = True
    if n < 2:
        return 0 # Should not happen for n >= 1
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            is_prime = False
            break
    if is_prime:
        return 1

    # Find a non-trivial factorization n = m * k where m > 1, k > 1
    # We just need to find the smallest factor m > 1
    m = 2
    while m * m <= n:
        if n % m == 0:
            break
        m += 1

    if m * m > n:
        # n must be prime, but the check above already handled this. 
        # Defensive check: if we reach here and it's not prime, something is wrong.
        return 1 

    k = n // m

    # Apply the recursive formula: h(n) = h(m*k) = m*h(k) + k*h(m)
    # NOTE: Since the relation is symmetric, we can pick any factorization.
    return m * calculate_h(k) + k * calculate_h(m)

# --- Testing specific composite numbers ---
test_numbers = [4, 6, 8, 12]
results = {}
for n in test_numbers:
    results[n] = calculate_h(n)

print("Calculated h(n) values for composite numbers:")
print(results)

# Check the derived solutions p=2, 3, 5 against the limit 4000.
solutions = {2, 3, 5}
limit = 4000
results = []

for p in solutions:
    # Since k=p, we calculate p^p
    n = p**p
    if n <= limit:
        results.append(n)

print(results)

